#!/usr/bin/env python3
"""Write test/sql/api_every_function.test: one query per generated function (stdlib, deterministic).

    python3 test/fixtures/build_api_tests.py > test/sql/api_every_function.test

Every spec-driven function is called against the replay server with only the arguments it
cannot do without (a required Stripe parameter, or the id of an object Stripe cannot list) and
must return at least one row with a non-NULL raw JSON column. Nested lists run without a
parent id, so the fan-out over every parent is exercised for each of them.
"""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
GEN = json.loads((ROOT / "src/stripe/generated/endpoints.json").read_text())
DATA = json.loads((ROOT / "test/fixtures/stripe-api-account.json").read_text())

# Values for arguments Stripe requires (the replay data has matching objects where it matters).
REQUIRED = {
    ("credit_note_preview", "invoice"): "'in_1'",
    ("credit_note_preview_lines", "invoice"): "'in_1'",
    ("meter_event_summaries", "customer"): "'cus_margaret'",
    ("meter_event_summaries", "start_time"): "TIMESTAMPTZ '2026-11-01 00:00:00+00'",
    ("meter_event_summaries", "end_time"): "TIMESTAMPTZ '2026-11-04 00:00:00+00'",
    ("app_secret", "name"): "'vgi-secret-0'",
    ("association", "payment_intent"): "'pi_1'",
    ("locations", "type"): "'performance'",
    ("credit_balance_summary", "filter_type"): "'credit_grant'",
}
EXTRA = {
    "meter_event_summaries": ["meter_id := 'mtr_api_calls'"],
    "credit_balance_summary": ["customer := 'cus_ada'", "filter_credit_grant := 'credgr_x'"],
}


def main() -> None:
    out = [
        "# name: test/sql/api_every_function.test",
        "# description: every spec-driven function returns rows from the replay server (generated by test/fixtures/build_api_tests.py)",
        "# group: [stripe]",
        "",
        "require vgi",
        "",
        "require-env STRIPE_WORKER",
        "",
        "require-env STRIPE_FIXTURE_URL",
        "",
        "statement ok",
        "LOAD json;",
        "",
        "statement ok",
        "ATTACH 'stripe' (TYPE vgi, LOCATION '{STRIPE_WORKER}');",
        "",
        "statement ok",
        "CREATE SECRET stripe_fixture (TYPE stripe, API_KEY 'sk_test_fixture', BASE_URL '{STRIPE_FIXTURE_URL}');",
        "",
    ]
    for ep in sorted(GEN["endpoints"], key=lambda e: (e["schema"], e["name"])):
        args = list(EXTRA.get(ep["name"], []))
        for a in ep["args"]:
            if (ep["name"], a["n"]) in REQUIRED:
                args.append(f"{a['n']} := {REQUIRED[(ep['name'], a['n'])]}")
            elif a["req"]:
                raise SystemExit(f"build_api_tests: no value for required {ep['name']}.{a['n']}")
        fan = ep["fanout"]
        if fan and fan["parent"] is None:
            if ep["mode"] == "retrieve":
                pid = DATA["objects"][ep["path"]][0]["id"]
            else:
                rows = DATA["lists"][ep["path"]]
                pid = rows[0]["parent"]
            args.insert(0, f"{fan['arg']} := '{pid}'")
        call = f"stripe.{ep['schema']}.{ep['name']}({', '.join(args)})"
        out += [
            f"# {ep['path']}",
            "query I",
            f"SELECT count(*) > 0 AND bool_and(raw IS NOT NULL) FROM {call};",
            "----",
            "true",
            "",
        ]
    print("\n".join(out))


if __name__ == "__main__":
    main()
